import {getAddress,keccak256,sha256,toUtf8Bytes,AbiCoder} from '../vendor/ethers.min.js';
export const COMPILER='anima.release-calendar/1.0.0';
const uint=(v,max=(1n<<112n)-1n)=>{if(!/^\d+$/.test(String(v)))throw Error('Invalid unsigned integer.');const n=BigInt(v);if(n>max)throw Error('Integer exceeds the calendar range.');return String(n);};
const time=v=>Number(uint(v,1000000000000n));
export function normalizeSnapshot(s){
  if(s?.schema!=='anima.vault-snapshot/1'||!Array.isArray(s.locks)||s.locks.length>48||!/^0x[0-9a-f]{64}$/i.test(s.block?.hash||''))throw Error('Use a pinned snapshot containing at most 48 selected locks.');
  const account=getAddress(s.account),locks=s.locks.map(l=>{
    const x={id:uint(l.id),asset:getAddress(l.asset),beneficiary:getAddress(l.beneficiary),amount:uint(l.amount),released:uint(l.released),start:time(l.start),cliff:time(l.cliff),end:time(l.end),linear:l.linear,decimals:Number(l.decimals),symbol:String(l.symbol||'TOKEN').slice(0,20)};
    if(x.beneficiary!==account||BigInt(x.released)>BigInt(x.amount)||x.end<=x.start||x.cliff<x.start||x.cliff>x.end||typeof x.linear!=='boolean'||!x.linear&&x.cliff!==x.end||!Number.isInteger(x.decimals)||x.decimals<0||x.decimals>36)throw Error('Invalid vesting schedule or beneficiary.');return x;
  }).sort((a,b)=>BigInt(a.id)<BigInt(b.id)?-1:1);
  if(new Set(locks.map(l=>l.id)).size!==locks.length)throw Error('Duplicate lock IDs.');
  return {schema:s.schema,chainId:uint(s.chainId,(1n<<64n)-1n),collection:getAddress(s.collection),tokenId:uint(s.tokenId),account,vault:getAddress(s.vault),block:{number:uint(s.block.number),hash:s.block.hash.toLowerCase(),timestamp:time(s.block.timestamp)},locks};
}
export function vestedAt(lock,timestamp){const t=BigInt(Math.floor(timestamp)),start=BigInt(lock.start),cliff=BigInt(lock.cliff),end=BigInt(lock.end),amount=BigInt(lock.amount);if(t<cliff)return 0n;if(t>=end)return amount;return lock.linear?amount*(t-start)/(end-start):0n;}
export function availableAt(lock,timestamp){const n=vestedAt(lock,timestamp)-BigInt(lock.released);return n>0n?n:0n;}
const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function calendarICS(snapshot){
  const s=normalizeSnapshot(snapshot),date=t=>new Date(t*1000).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
  const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ANIMA//Release Calendar 1//EN','CALSCALE:GREGORIAN'];
  for(const l of s.locks)for(const [label,at] of l.cliff===l.end?[['Maturity',l.end]]:[['Cliff',l.cliff],['Maturity',l.end]])lines.push('BEGIN:VEVENT',`UID:${s.chainId}-${s.vault}-${l.id}-${label}@anima`, `DTSTAMP:${date(s.block.timestamp)}`,`DTSTART:${date(at)}`,`SUMMARY:ANIMA lock ${l.id} ${label}`,`DESCRIPTION:Read-only schedule for NFT ${s.tokenId}. Release requires a separate transaction.`, 'END:VEVENT');
  return lines.concat('END:VCALENDAR','').join('\r\n');
}
export function compileCalendar(input){
  const snapshot=normalizeSnapshot(input),data=JSON.stringify(snapshot).replaceAll('<','\\u003c'),requestHash=keccak256(toUtf8Bytes(JSON.stringify(snapshot)));
  const terms=keccak256(AbiCoder.defaultAbiCoder().encode(['string','string','bytes32'],['anima.release-calendar.job/1',COMPILER,requestHash]));
  const html=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ANIMA Release Calendar</title><style>body{margin:0;background:#04101c;color:#d6f1ff;font:15px system-ui;padding:24px}h1{font-size:clamp(24px,5vw,40px);font-weight:400}small,p{color:#92b8d1}label{display:block;margin:24px 0 8px}input{width:100%;accent-color:#67cdfb}article{border-top:1px solid #24485e;padding:18px 0;display:grid;gap:9px}progress{width:100%;height:12px;accent-color:#78daff}code{font-size:11px;overflow-wrap:anywhere}b{font-weight:500;color:#a4e4ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px}</style><h1>Release Calendar</h1><p>Built for NFT #${escape(snapshot.tokenId)} · ${snapshot.locks.length} selected locks</p><small>Frozen public snapshot at block ${escape(snapshot.block.number)}. This instrument has no wallet, network or spending authority.</small><label for="time">Explore the release schedule · <output id="date"></output></label><input id="time" type="range" min="0" max="1000" value="0"><div id="locks" class="grid"></div><p>Amounts available use the snapshot’s already-released totals. Later releases and schedule extensions require a refreshed snapshot.</p><details><summary>Source identity</summary><code>${escape(snapshot.collection)} / ${escape(snapshot.tokenId)}<br>${escape(snapshot.block.hash)}</code></details><script>const S=${data};const vestedAt=${vestedAt.toString()};const min=S.block.timestamp,max=Math.max(min+1,...S.locks.map(l=>l.end));const f=(n,d)=>{let s=n.toString().padStart(d+1,'0');return d?s.slice(0,-d)+'.'+s.slice(-d).replace(/0+$/,''):s;};const root=document.getElementById('locks');for(const l of S.locks){const a=document.createElement('article');a.innerHTML='<b></b><span></span><progress max="1000"></progress><small></small>';a.querySelector('b').textContent='Lock '+l.id+' · '+l.symbol;root.append(a);}function paint(){const t=Math.floor(min+(max-min)*Number(document.getElementById('time').value)/1000);document.getElementById('date').textContent=new Date(t*1000).toISOString();S.locks.forEach((l,i)=>{const v=vestedAt(l,t),r=BigInt(l.released),a=v>r?v-r:0n,e=root.children[i];e.querySelector('span').textContent=f(a,l.decimals)+' available / '+f(BigInt(l.amount),l.decimals)+' total';e.querySelector('progress').value=BigInt(l.amount)?Number(v*1000n/BigInt(l.amount)):0;e.querySelector('small').textContent=(l.linear?'Linear vesting':'Cliff release')+' · maturity '+new Date(l.end*1000).toISOString();});}document.getElementById('time').oninput=paint;paint();</script></html>`;
  const bytes=toUtf8Bytes(html);if(bytes.length>24576)throw Error('Calendar exceeds the onchain cartridge size; select fewer locks.');
  const contentHash=sha256(bytes),manifest={spec:'awe.cartridge/1',name:'Release Calendar · NFT #'+snapshot.tokenId,version:'1',engine:'html',entry:'sha256:'+contentHash.slice(2),contentHash,capabilities:[],settlement:'read-only',compiler:COMPILER,requestHash,source:{chainId:snapshot.chainId,collection:snapshot.collection,tokenId:snapshot.tokenId,blockHash:snapshot.block.hash}};
  const manifestJSON=JSON.stringify(manifest),deliverable=keccak256(AbiCoder.defaultAbiCoder().encode(['string','bytes32','bytes32','bytes32'],['anima.commissioned-cartridge/1',terms,contentHash,keccak256(toUtf8Bytes(manifestJSON))]));
  return {schema:'anima.instrument-deliverable/1',compiler:COMPILER,snapshot,terms,requestHash,contentHash,manifestJSON,html,deliverable,bytes:bytes.length};
}
export function validateCalendar(artifact){const expected=compileCalendar(artifact.snapshot);for(const key of ['compiler','terms','requestHash','contentHash','manifestJSON','html','deliverable'])if(artifact[key]!==expected[key])throw Error('Deliverable differs from the deterministic reviewed calendar.');return expected;}
